/**
 * Reemplaza el `<img>` estático de divider-brush.svg: misma cinta y curva,
 * pero el texto vive en un <textPath> que se desliza en loop sobre ella
 * (mismo mecanismo que la cinta curva de bobolobo.webflow.io, a menor
 * velocidad y escala). Se pausa si el usuario prefiere menos movimiento.
 *
 * `frase` y `velocidadSegundos` vienen del panel de administración
 * (retreat.cintaTexto / retreat.cintaVelocidadSegundos, editables en
 * "Contenido" → "Qué es Encaminados"); acá la frase solo se pasa a mayúsculas.
 */
export default function WaveBanner({ frase, velocidadSegundos }: { frase: string; velocidadSegundos: number }) {
  const [animar, setAnimar] = useState(false);

  useEffect(() => {
    setAnimar(!window.matchMedia("(prefers-reduced-motion: reduce)").matches);
  }, []);

  const fraseMayus = frase.toUpperCase();
  const textoLoop = `${fraseMayus}                    •                    ${fraseMayus}                    •                    ${fraseMayus}                    •                    `;

  return (
    <svg
      viewBox="0 -26 1590.65 129.2612"
      className="h-auto w-[318%] max-w-none -ml-[109%] sm:w-[106%] sm:-ml-[3%]"
      role="img"
      aria-label={frase}
    >
      <defs>
        <path id="wave-banner-curva" d={CURVA} />
      </defs>

      <use href="#wave-banner-curva" stroke="var(--color-icon-bg)" strokeWidth={60} strokeLinecap="square" strokeLinejoin="round" fill="none" />

      <text
        fill="#CD5F37"
        fontFamily="var(--font-body)"
        fontWeight={500}
        fontSize={32}
        letterSpacing="0.02em"
        dominantBaseline="middle"
      >
        <textPath href="#wave-banner-curva" startOffset="0%">
          {textoLoop}
          {animar && (
            <animate
              attributeName="startOffset"
              from="0%"
              to="-100%"
              dur={`${velocidadSegundos}s`}
              repeatCount="indefinite"
            />
          )}
        </textPath>
      </text>
    </svg>
  );
}
